/// <summary>
///     The <c>AVACustTable_NewCustomerBtn_Extension</c> class is the extension of FormControl <c>AVANewCustomer</c> in form <c>custTable</c>
/// </summary>
[ExtensionOf(formControlStr(CustTable, AVANewCustomer))]
final class AVACustTable_AVANewCustomerBtn_Extension
{
}

Method.Source:
 /// <summary>
 ///    AVA <c>Clicked</c> class.
 /// </summary>
public void clicked()
 {
     Args            locArgs;
     MenuFunction    locMenuFunction;

     if(AVASalesParameters::checkDirectCustomerCreation(NoYes::Yes))
     {
         locArgs = new Args();
         locArgs.menuItemType(MenuItemType::Display);
         locArgs.menuItemName(menuItemDisplayStr(CustomerquickCreate));
         locArgs.openMode(OpenMode::New);
         locArgs.name('AVANewCustomer');

         locMenuFunction = new MenuFunction(menuItemDisplayStr(CustomerquickCreate), MenuItemType::Display);

         locMenuFunction.run(locArgs);
     }

     next clicked();
 }
